using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver(),
    WriteIndented = true
};

// --- 1. Strongly-typed metadata retrieval: GetTypeInfo<T>() ---
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo for: {personInfo.Type.Name}");
Console.WriteLine($"Properties: {personInfo.Properties.Count}");

// Use it to serialize
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");
Console.WriteLine();

// --- 2. Probe without throwing: TryGetTypeInfo ---
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded → {info!.Type.Name}");
}

// Now try a type that has NO resolver coverage (use an empty resolver)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty composite — resolves nothing
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("Unexpectedly found metadata!");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) on limited options → not available (no exception thrown)");
}

// Record used for the demo
public record Person(string Name, int Age);

